import React, { useState, useEffect } from 'react';
import api from '../api';
import PreShiftForm from './PreShiftForm';

function CalendarView({ onDateSelect }) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [calendarData, setCalendarData] = useState({ daily: {}, weekly: {}, monthly: {} });
  const [preshiftDates, setPreshiftDates] = useState([]);
  const [viewMode, setViewMode] = useState('tasks'); // 'tasks' or 'preshift'
  const [selectedDate, setSelectedDate] = useState(null);
  const [showPreShiftForm, setShowPreShiftForm] = useState(false);

  useEffect(() => {
    loadCalendarData();
  }, [currentDate, viewMode]);

  const loadCalendarData = async () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth() + 1;

    if (viewMode === 'tasks') {
      try {
        const data = await api.getCalendarData(year, month);
        setCalendarData(data);
      } catch (error) {
        console.error('Error loading calendar data:', error);
      }
    } else {
      // Load pre-shift form dates
      try {
        const dates = await api.getPreShiftFormDates(year, month);
        setPreshiftDates(dates);
      } catch (error) {
        console.error('Error loading pre-shift dates:', error);
      }
    }
  };

  const formatDateForDisplay = (dateStr) => {
    const date = new Date(dateStr + 'T12:00:00');
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const day = date.getDate().toString().padStart(2, '0');
    const year = date.getFullYear();
    return `${month}/${day}/${year}`;
  };

  const handlePrevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1));
  };

  const handleDateClick = (dateStr) => {
    if (viewMode === 'preshift') {
      setSelectedDate(dateStr);
      setShowPreShiftForm(true);
    } else {
      onDateSelect(dateStr);
    }
  };

  const handleClosePreShiftForm = () => {
    setShowPreShiftForm(false);
    setSelectedDate(null);
    loadCalendarData(); // Reload to update which dates have forms
  };

  const getDaysInMonth = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const daysInMonth = lastDay.getDate();
    const startingDayOfWeek = firstDay.getDay();

    const days = [];

    // Add empty cells for days before the month starts
    for (let i = 0; i < startingDayOfWeek; i++) {
      days.push(null);
    }

    // Add all days in the month
    for (let day = 1; day <= daysInMonth; day++) {
      days.push(day);
    }

    return days;
  };

  const getDateString = (day) => {
    if (!day) return null;
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    return new Date(year, month, day).toISOString().split('T')[0];
  };

  const getCompletionPercentage = (day) => {
    const dateStr = getDateString(day);
    if (!dateStr) return 0;

    const dailyData = calendarData.daily[dateStr];
    return dailyData ? dailyData.percentage : 0;
  };

  const hasPreShiftForm = (day) => {
    const dateStr = getDateString(day);
    return preshiftDates.includes(dateStr);
  };

  const getCompletionColor = (percentage) => {
    if (percentage === 0) return '#e0e0e0';
    if (percentage < 50) return '#e74c3c';
    if (percentage < 100) return '#f39c12';
    return '#27ae60';
  };

  if (showPreShiftForm && selectedDate) {
    return (
      <PreShiftForm 
        selectedDate={selectedDate}
        onClose={handleClosePreShiftForm}
      />
    );
  }

  const days = getDaysInMonth();

  return (
    <div className="main-content">
      <div className="page-header">
        <div>
          <h1>Calendar View</h1>
          <p>Overview of task completion and pre-shift forms</p>
        </div>

        <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
          <label style={{ fontWeight: '600' }}>View:</label>
          <select
            className="form-control"
            value={viewMode}
            onChange={(e) => setViewMode(e.target.value)}
            style={{ width: '200px' }}
          >
            <option value="tasks">Task Calendar</option>
            <option value="preshift">Pre-Shift Forms</option>
          </select>
        </div>
      </div>

      <div className="calendar-container">
        <div className="calendar-header">
          <button className="btn btn-secondary" onClick={handlePrevMonth}>
            ← Previous
          </button>
          <h2>
            {currentDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
          </h2>
          <button className="btn btn-secondary" onClick={handleNextMonth}>
            Next →
          </button>
        </div>

        {viewMode === 'tasks' && (
          <div className="calendar-legend">
            <div className="legend-item">
              <div className="legend-color" style={{ backgroundColor: '#27ae60' }}></div>
              <span>100% Complete</span>
            </div>
            <div className="legend-item">
              <div className="legend-color" style={{ backgroundColor: '#f39c12' }}></div>
              <span>Partially Complete</span>
            </div>
            <div className="legend-item">
              <div className="legend-color" style={{ backgroundColor: '#e74c3c' }}></div>
              <span>Low Completion</span>
            </div>
            <div className="legend-item">
              <div className="legend-color" style={{ backgroundColor: '#e0e0e0' }}></div>
              <span>No Tasks</span>
            </div>
          </div>
        )}

        <div className="calendar-grid">
          <div className="calendar-day-header">Sun</div>
          <div className="calendar-day-header">Mon</div>
          <div className="calendar-day-header">Tue</div>
          <div className="calendar-day-header">Wed</div>
          <div className="calendar-day-header">Thu</div>
          <div className="calendar-day-header">Fri</div>
          <div className="calendar-day-header">Sat</div>

          {days.map((day, index) => {
            if (!day) {
              return <div key={`empty-${index}`} className="calendar-day empty"></div>;
            }

            const dateStr = getDateString(day);
            const isToday = dateStr === new Date().toISOString().split('T')[0];

            if (viewMode === 'tasks') {
              const percentage = getCompletionPercentage(day);
              const color = getCompletionColor(percentage);

              return (
                <div
                  key={day}
                  className={`calendar-day ${isToday ? 'today' : ''}`}
                  onClick={() => handleDateClick(dateStr)}
                  style={{ cursor: 'pointer' }}
                >
                  <div className="calendar-day-number">{day}</div>
                  <div 
                    className="calendar-completion"
                    style={{ backgroundColor: color }}
                  >
                    {percentage}%
                  </div>
                </div>
              );
            } else {
              // Pre-shift mode
              const hasFilled = hasPreShiftForm(day);

              return (
                <div
                  key={day}
                  className={`calendar-day ${isToday ? 'today' : ''}`}
                  onClick={() => handleDateClick(dateStr)}
                  style={{ 
                    cursor: 'pointer',
                    backgroundColor: hasFilled ? '#e8f5e9' : 'white'
                  }}
                >
                  <div className="calendar-day-number">{day}</div>
                  {hasFilled && (
                    <div style={{
                      fontSize: '12px',
                      color: '#27ae60',
                      fontWeight: '600',
                      marginTop: '5px'
                    }}>
                      ✓ Filled
                    </div>
                  )}
                </div>
              );
            }
          })}
        </div>
      </div>
    </div>
  );
}

export default CalendarView;
